def sync_decor(f):
    @wraps(f)
    def w(*a, **k):
        return f(*a, **k)
    return w

def gen_decor(f):
    @wraps(f)
    def w(*a, **k):
        yield from f(*a, **k)
    return w

def agen_decor(f):
    @wraps(f)
    async def w(*a, **k):
        async for x in f(*a, **k):
            yield x
    return w

app = FastAPI()
log = []

@cache
@sync_decor
def sync_dep() -> int:
    log.append("sync")
    return 1

@cache
@gen_decor
def gen_dep() -> Iterator[str]:
    log.append("gen-open")
    yield "g"
    log.append("gen-close")

@cache
@agen_decor
async def agen_dep() -> AsyncIterator[str]:
    log.append("agen-open")
    yield "a"
    log.append("agen-close")

@app.get("/all")
